			row[StmReportRunSchema.Constants.RRI_SystemCreateUser             ] = "";
			row[StmReportRunSchema.Constants.RRI_SystemLastEditTimeUtc        ] = DBNull.Value;
			row[StmReportRunSchema.Constants.RRI_SystemLastEditUser           ] = "";
			row[StmReportRunSchema.Constants.RRI_TotalRunDurationMilliseconds ] = (int)0;
		}

